import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        if (reportId == null || !reportId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        // Validate direction parameter
        if (direction != null && !direction.equalsIgnoreCase("ASC")
                && !direction.equalsIgnoreCase("DESC")) {
            direction = "ASC";
        }

        // sortCol is used for dynamic ORDER BY - validated against allowlist
        String[] allowedCols = {"created_at", "amount", "status", "customer_name"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String col : allowedCols) {
                if (col.equals(sortCol)) {
                    validSort = true;
                    break;
                }
            }
        }
        if (!validSort) {
            sortCol = "created_at";
        }

        String filterExpr = req.getParameter("filter");
        String query = buildQuery(reportId, sortCol, direction, filterExpr);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) sb.append(",");
                sb.append("{\"id\":").append(rs.getInt("id"));
                sb.append(",\"amount\":").append(rs.getDouble("amount"));
                sb.append(",\"status\":\"")
                  .append(rs.getString("status").replace("\"", "\\\""))
                  .append("\"}");
                first = false;
            }
            sb.append("]");
            resp.getWriter().write(sb.toString());
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String buildQuery(String reportId, String sortCol, String direction, String filterExpr) {
        StringBuilder q = new StringBuilder();
        q.append("SELECT id, amount, status FROM transactions WHERE report_id = ");
        q.append(reportId);

        if (filterExpr != null && !filterExpr.isEmpty()) {
            // Apply user-provided filter expression for advanced search
            q.append(" AND (").append(filterExpr).append(")");
        }

        q.append(" ORDER BY ").append(sortCol).append(" ").append(direction);
        q.append(" LIMIT 500");
        return q.toString();
    }

    @Override
    public void init() throws ServletException {
        try {
            Class.forName("org.postgresql.Driver");
        } catch (ClassNotFoundException e) {
            throw new ServletException("PostgreSQL driver not found", e);
        }
    }
}
